'use strict';
const find=s=>document.querySelector(s);let invitation=null,qr=null,link=/^[A-Za-z0-9_-]{43}$/.test(location.hash.slice(1))?location.hash.slice(1):'';if(link)history.replaceState(null,'',location.pathname);
async function request(path,body){const r=await fetch('/api/invite/'+path,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json','X-Temu-Invite':'1'}:{},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(12000)});const data=await r.json();if(!r.ok)throw Error(data.error||'Akses tidak tersedia.');return data;}
function lock(message){find('#invitation').hidden=true;find('#gate').hidden=false;find('#gate-status').textContent=message;const video=find('#wedding-film');video.pause();video.removeAttribute('src');video.removeAttribute('poster');video.load();document.querySelectorAll('#invitation img').forEach(img=>img.removeAttribute('src'));find('#guest-qr').replaceChildren();invitation=null;qr=null;document.title='Undangan Pribadi';}
async function display(){
 const data=await request('view');invitation=data;const e=data.event,w=e.wedding||{},g=data.guest;
 const a=w.firstName||'Mempelai pertama',b=w.secondName||'Mempelai kedua',date=e.date?new Date(e.date+'T12:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'}):'Tanggal akan diinformasikan';
 find('#first-name').textContent=a;find('#second-name').textContent=b;find('#monogram').textContent=a.charAt(0)+' / '+b.charAt(0);find('#signature').textContent=a+' & '+b;find('#closing-names').textContent=a+' & '+b;find('#cover-date').textContent=date;find('#event-date').textContent=e.date?new Date(e.date+'T12:00:00').toLocaleDateString('id-ID',{weekday:'long'})+', '+date:date;
 find('#guest-name').textContent=g.name;find('#qr-name').textContent=g.name;find('#quota-note').textContent='Undangan pribadi untuk '+g.name+', berlaku bagi '+g.quota+' orang.';
 find('#cover-venue').textContent=w.venue||'Lokasi akan diinformasikan';find('#venue').textContent=w.venue||'Lokasi akan diinformasikan';find('#address').textContent=w.address||'Alamat dan petunjuk perjalanan tersedia melalui peta.';find('#ceremony-time').textContent=w.ceremonyTime||'Waktu akan diinformasikan';find('#reception-time').textContent=w.receptionTime||'Waktu akan diinformasikan';
 const maps=find('#maps-link');maps.hidden=true;if(w.mapsURL){try{const u=new URL(w.mapsURL);if(u.protocol==='https:'){maps.href=u.href;maps.hidden=false;}}catch{}}
 for(let i=1;i<=3;i++)find('#portrait-'+i).src='/api/invite/media/portrait-'+i+'.jpg';find('#hero-photo').src='/api/invite/media/portrait-3.jpg';const video=find('#wedding-film');video.src='/api/invite/media/film.mp4';video.poster='/api/invite/media/portrait-2.jpg';
 const code=qrcode(0,'M');code.addData(JSON.stringify({v:1,event:e.id,code:g.code}));code.make();find('#guest-qr').innerHTML=code.createSvgTag(5,20);find('#gate').hidden=true;find('#invitation').hidden=false;find('#gate-status').textContent='';document.title=a+' & '+b+' — Undangan';qr=await TemuInvitations.qrFile(g,e);
}
find('#unlock').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;try{if(!link)throw Error('Buka kembali tautan pribadi dari pengundang.');await request('unlock',{link,code:find('#access-code').value.trim()});find('#access-code').value='';await display();}catch(e){lock(e.message);}finally{button.disabled=false;}};
find('#logout').onclick=async()=>{try{await request('logout',{});lock('Akses ditutup. Buka tautan pribadi dan masukkan kode untuk masuk kembali.');link='';}catch{lock('Konten disembunyikan. Sambungkan internet untuk mengakhiri sesi di server.');}};
find('#save-guest-qr').onclick=async()=>{try{if(!qr)throw Error('QR sedang disiapkan.');const current=await request('view');qr=await TemuInvitations.qrFile(current.guest,current.event);const a=document.createElement('a');a.href=URL.createObjectURL(qr);a.download='QR-undangan.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);find('#qr-status').textContent='QR disimpan. Tunjukkan gambar ini kepada petugas saat tiba.';}catch(e){find('#qr-status').textContent=e.message;}};
window.addEventListener('pagehide',()=>lock('Buka kembali untuk melanjutkan.'));
window.addEventListener('pageshow',e=>{if(e.persisted)display().catch(e=>lock(e.message));});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&invitation)request('view').catch(e=>lock(e.message));});
setInterval(()=>{if(invitation)request('view').catch(e=>lock(e.message));},60000);
// A fresh personal link always requires its own code, even if another invitation has a session.
if(link)lock('Masukkan kode akses pribadi yang Anda terima.');else display().catch(()=>lock('Buka tautan undangan pribadi, lalu masukkan kode akses Anda.'));
window.addEventListener('hashchange',()=>{const candidate=location.hash.slice(1);if(/^[A-Za-z0-9_-]{43}$/.test(candidate)){link=candidate;history.replaceState(null,'',location.pathname);lock('Masukkan kode akses pribadi yang Anda terima.');}});
